"""Generate supplementary segmentation tables from completed prospective runs only."""
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=Path(__file__).resolve().parent


def load(path): return json.loads((ROOT/path).read_text(encoding='utf-8'))


def main():
    prefix='sponge-sim/results/confirmation_20261106/'
    runs=[('CPU, four exposed logical processors',prefix+'m2_cpu4_full_20261106/summary_verified.json'),
          ('RTX 5060 Ti',prefix+'m2_gpu_full_20261106/summary_verified.json')]
    lines=[r'% Generated by segmentation_extension/make_extension.py; do not edit numbers.',
           r'\section{Prospective segmentation extension}',r'\label{app:segmentation}',
           r'This extension was preregistered after the historical GPU observations had been inspected; it does not retroactively preregister them. It asks whether instance-mask construction, rather than NMS, supplies a larger per-object cost. Device measurements and attack counts use the first 20 lexicographically ordered images of COCO128-seg, not an independent held-out cohort. The pretrained weights and all image identities are bound by SHA-256 manifests. Digital full-image perturbations are used; physical patches are not evaluated here.',
           r'\subsection{Synthetic mask workload and measurement quality}',
           r'YOLOv8n-seg is evaluated in FP32 at $640\times640$, confidence 0.25 and IoU 0.45. NMS uses a fixed torchvision kernel. Real image forward and NMS are followed by deterministic injected mask coefficients and boxes at $K\in\{0,10,50,100,300\}$. Total time is measured directly; mask time is also measured separately. The proto-resolution option uses \texttt{upsample=False}, as in the historical microbenchmark, and is not presented as the default deployed predictor. Full-resolution masks use \texttt{process\_mask\_native}.',
           r'Each image has five repetitions, randomized condition order, two $K=0$ A/A copies, and a fixed-image forward reference before each image. GPU timers synchronize on both boundaries. CPU affinity is read back and verified under load. The rented host reports an i7-12700K name but exposes 18 homogeneous logical processors; P/E-core or physical-core identities cannot be inferred. The CPU condition below pins logical processors 2--5 with four intra-op threads.',
           r'The ratio uses $K=10$ as baseline, per-image medians followed by a geometric mean; confidence intervals resample images 20,000 times with seed 20261106. The MDE is an 80\%-power central-$t$ approximation on the log A/A ratio. $K^*$ is the smallest tested $K>10$ whose lower ratio confidence limit exceeds $\exp(\mathrm{MDE}_{\log})$.',
           r'\begin{table*}[t]\centering',r'\caption{Prospective synthetic mask workload. Ratios are directly measured total time at $K=300$ relative to $K=10$, conditional on the fixed cohort. Only runs meeting the registered quality gate are included.}',
           r'\label{tab:seg-device}',r'\begin{tabular}{llrrrr}\toprule',
           r'Device & Mask construction & Total ratio [95\% CI] & MDE (\%) & $K^*$ & Drift flags\\\midrule']
    sources={}
    for label,path in runs:
        s=load(path); assert s['quality_pass'] and s['complete']
        sources[path]=hashlib.sha256((ROOT/path).read_bytes()).hexdigest()
        for retina,name in [('False','Proto resolution'),('True','Full resolution')]:
            r=s['ratios'][retina+'|300']; m=s['mde'][retina]['frac']*100
            lines.append(f"{label} & {name} & {r['ratio']:.3f} [{r['ci95'][0]:.3f}, {r['ci95'][1]:.3f}] & {m:.2f} & {s['k_star'][retina]} & {len(s['flagged'])} \\\\")
    lines += [r'\bottomrule\end{tabular}\end{table*}',
              r'\begin{figure*}[t]\centering\includegraphics[width=0.85\textwidth]{segmentation_extension/mask_dose_response.pdf}\caption{Synthetic mask-workload dose response on the two quality-accepted device runs. Shading shows image-bootstrap 95\% intervals; the ratio is relative to $K=10$.}\label{fig:seg-dose}\end{figure*}',
              r'The CPU-four-processor run has zero flagged reference points and both load checks pass; the GPU run has two flagged points, within the allowed maximum of two. A separate single-processor CPU run has ten flagged points and is excluded from this table. Earlier laptop runs remain rejected. These synthetic controls establish a cost surface, not attack efficacy.',
              r'\subsection{Real perturbations and native NMS-free transfer}']
    mp=prefix+'m3_native_full_20261106/summary.json'; m=load(mp); assert m['complete'] and not m['smoke']
    sources[mp]=hashlib.sha256((ROOT/mp).read_bytes()).hexdigest()
    v=m['models']['k_v8']; t=m['models']['k26_native']; n=m['n_images']
    lines.append(f"The prospective attack confirmation reuses the historical full-image PGD objective and fixed budget ($L_\\infty=16/255$, 100 steps, step size $2/255$). It evaluates the final iterate, rather than the best iterate over a trajectory. On YOLOv8n-seg, median retained count changes from {v['clean_median']:g} to {v['attacked_median']:g}; {v['reach100']}/{n} images reach $K\\ge100$ and {v['reach300']}/{n} reach the cap of 300.")
    lines.append(f"The SAME perturbations are transferred to YOLO26n-seg with its one-to-one head explicitly enabled ($\\texttt{{end2end=True}}$). Counts come directly from confidence column 4 of the native $[1,300,38]$ output at threshold 0.25, without applying NMS. The target median changes from {t['clean_median']:g} to {t['attacked_median']:g}; {t['reach50']}/{n} images reach $K\\ge50$. Thus this experiment does not reproduce high-count transfer to the native NMS-free path. It does not establish immunity to a target-specific attack. Earlier high-count YOLO26 observations used a different inference/counting path and cannot support a native NMS-free claim.")
    lines += [r'\subsection{Backend identity and real-pipeline timing}',
              r'Inspection of the installed Ultralytics source identifies import-dependent dispatch: when torchvision is present in \texttt{sys.modules}, the wrapper calls \texttt{torchvision.ops.nms}; otherwise it calls \texttt{TorchNMS.nms}. The original scripts differed in this import. A same-tensor kernel comparison reproduced the discrepancy, but that full diagnostic failed its reference-drift gate and is retained as diagnostic evidence rather than a clean headline latency estimate. A separately registered fixed-kernel real-pipeline confirmation is reported in the accompanying evidence package. This source-level distinction precludes attributing the historical large slowdown to mask construction alone.',
              r'\subsection{Clean-data accuracy of output and candidate caps}']
    expanded_path='sponge-sim/results/validation_500_20261106/full/summary.json'
    if (ROOT/expanded_path).exists():
        expanded=load(expanded_path)
        assert expanded['complete'] and not expanded['smoke'] and expanded['n_images']==500
        sources[expanded_path]=hashlib.sha256((ROOT/expanded_path).read_bytes()).hexdigest()
        extra=[r'\subsection{Expansion to a disjoint 500-image validation cohort}',
            r'After the COCO128 observations, a separate prospective study locks 500 of the 5,000 official COCO val2017 images by uniform sampling without replacement (seed 20261106). These images are disjoint from the earlier 20-image cohort. The budget and final-iterate rule are unchanged; FP32 evaluation uses a prospectively fixed batch size of four. Batched kernels can differ numerically from batch-one execution. Each source model optimizes its own perturbations; the YOLO26 target receives the same perturbations optimized on YOLOv8n. Cohorts are reported separately and are not pooled.',
            r'\begin{table*}[t]\centering\caption{New COCO-val500 count study. Intervals for medians resample images 20,000 times; proportion intervals use Wilson 95\% bounds. The shared cutoff $K=50$ is a count endpoint, not a calibrated latency threshold for every model.}\label{tab:seg-val500}',
            r'\begin{tabular}{lrrlr}\toprule Model/path & Images & Clean median $K$ & Attacked median $K$ [95\% CI] & $K\ge50$ count [95\% fraction CI]\\\midrule']
        rs=[('YOLOv8n-seg',expanded['models']['yolov8n-seg.pt']['baseline']),
            ('YOLO11n-seg',expanded['models']['yolo11n-seg.pt']['baseline']),
            ('YOLO26 native, transfer',expanded['native26'])]
        for label,row in rs:
            ci=row['attacked_median_ci95'];reach=row['reach']['50'];bounds=reach['wilson_ci95']
            extra.append(f"{label} & 500 & {row['clean_median']:g} & {row['attacked_median']:g} [{ci[0]:g}, {ci[1]:g}] & {reach['count']}/500 [{100*bounds[0]:.2f}\\%, {100*bounds[1]:.2f}\\%] \\\\")
        extra += [r'\bottomrule\end{tabular}\end{table*}',
            r'\begin{figure*}[t]\centering\includegraphics[width=0.95\textwidth]{segmentation_extension/val500_counts.pdf}\caption{Disjoint COCO-val500 cohort. Left: empirical count distributions; dashed curves are clean source inputs, solid curves are attacked source inputs or native transfer. The terminal mass at $K=300$ is the output cap. Right: median candidate counts reaching the fixed NMS kernel. Workload counts do not by themselves establish latency reduction or denial of service.}\label{fig:seg-val500}\end{figure*}',
            r'The expanded study includes all outcomes at four cap settings and preserves float32 perturbation arrays, native outputs and hashes. Attack/count inputs use direct square resizing, whereas the separate clean-accuracy validation uses letterboxing; these do not define a jointly matched accuracy--latency curve. Source-model comparisons are descriptive, not causal attribution to architecture. Reaching a count cutoff can include images already above the cutoff when clean; paired gains and newly crossing images are reported in the evidence report. This count study does not convert rejected timing sessions into valid latency evidence and does not establish target-specific robustness of YOLO26.']
        index=lines.index(r'\subsection{Backend identity and real-pipeline timing}')
        lines[index:index]=extra
    cp='sponge-sim/results/coco_defense_20261106/full_remote/results.jsonl'
    records=[json.loads(x) for x in (ROOT/cp).read_text().splitlines()]; assert len(records)==8 and all(r['seen']==5000 for r in records)
    sources[cp]=hashlib.sha256((ROOT/cp).read_bytes()).hexdigest()
    lines += [r'All 5,000 COCO val2017 images are evaluated using Ultralytics polygon-label segmentation metrics, not an independently recomputed official COCO API score. Inference uses $640$-px letterboxing, FP32, batch size 8, confidence 0.001, IoU 0.7 and workers 0. The lower confidence threshold is the fixed accuracy-evaluation setting, distinct from the attack threshold. Detection-level metric inputs are retained for replay.',
              r'\begin{table}[t]\centering',r'\caption{Full validation segmentation mAP50--95 and absolute change in percentage points.}',r'\label{tab:seg-defense}',
              r'\begin{tabular}{llrr}\toprule Model & Setting & mAP (\%) & $\Delta$ (pp)\\\midrule']
    for model in ['yolov8n-seg.pt','yolo11n-seg.pt']:
        rs=[r for r in records if r['model']==model];base=next(r['results']['metrics/mAP50-95(M)'] for r in rs if r['variant']=='baseline')
        for r in rs:
            val=r['results']['metrics/mAP50-95(M)']; name=dict(baseline='Baseline',maxdet50='Output cap 50',prenms300='Pre-NMS cap 300',prenms1000='Pre-NMS cap 1000')[r['variant']]
            delta=100*(val-base)
            if abs(delta)<.005: delta=0.0
            lines.append(f"{model.replace('.pt','')} & {name} & {100*val:.2f} & {delta:+.2f} \\\\")
    lines += [r'\bottomrule\end{tabular}\end{table}',
              r'An output cap limits the number of masks but does not bound work before NMS. A pre-NMS cap limits candidate workload and has a separate accuracy cost. These clean-data results alone do not establish attack resistance or statistical equivalence. No significance claim is inferred from small descriptive mAP differences.',
              r'\paragraph{Reproducibility and limits.} The device and native-count runs are registered under \texttt{prereg-m2-m3-confirmation-20261106}, with an explicit native-head amendment before count observations. Accuracy evaluation is registered under \texttt{prereg-coco-defense-20261106}; implementation-only amendments and failed smoke runs are retained. The generated source map lists every table input. The study covers one rented host/GPU, fixed small timing/attack cohorts, synthetic mask-workload controls, and digital full-image attacks. It does not establish camera or edge-device denial of service.']
    cap_path='_provenance/codex_gpu_20261106/cap_full_20261106/raw.jsonl'
    caps=[json.loads(x) for x in (ROOT/cap_path).read_text().splitlines()]
    attacked=[r for r in caps if r['kind']=='counts' and r['arm']=='attacked']
    base=[r for r in attacked if r['variant']=='baseline'];output=[r for r in attacked if r['variant']=='maxdet50'];pre=[r for r in attacked if r['variant']=='prenms300']
    assert len(base)==len(output)==len(pre)==20
    assert [r['kernel_n'] for r in base]==[r['kernel_n'] for r in output]
    assert all(r['kernel_n']==300 for r in pre)
    import numpy as np
    lines.insert(-1,f"A separately registered count-only replay on the 20 frozen attacked inputs confirms the boundary distinction: an output cap of 50 leaves the kernel input count unchanged ({min(r['kernel_n'] for r in base)}--{max(r['kernel_n'] for r in base)}), whereas the pre-NMS cap of 300 restricts the kernel to 300 candidates on every image. The retained-count median after that pre-NMS cap is {np.median([r['k'] for r in pre]):g}; this does not establish elimination of mask cost or a measured latency benefit.")
    sources[cap_path]=hashlib.sha256((ROOT/cap_path).read_bytes()).hexdigest()
    # Every published section is required, including failed controls. Missing
    # negative evidence must stop regeneration rather than silently disappear.
    for name in ('nested1500','laptop_cpu','laptop_defense','laptop_components','laptop_reference_trace','laptop_pcores'):
        path=OUT/f'{name}.tex'
        sources[f'paper_en/segmentation_extension/{name}.tex']=hashlib.sha256(path.read_bytes()).hexdigest()
        lines.append(f'\\input{{segmentation_extension/{name}}}')
    (OUT/'extension.tex').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    (OUT/'sources.json').write_text(json.dumps(sources,indent=2))
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(6.8,3.5),layout='constrained')
    for index,(label,path) in enumerate(runs):
        s=load(path)
        for retina,mask_name in [('False','proto resolution'),('True','full resolution')]:
            rs=[s['ratios'][retina+'|'+str(k)] for k in (50,100,300)]
            x=[10,50,100,300];y=[1]+[r['ratio'] for r in rs]
            line,=ax.plot(x,y,marker='o',linestyle='-' if retina=='True' else '--',
                         label=('CPU, 4 exposed processors' if index==0 else 'RTX 5060 Ti')+', '+mask_name)
            ax.fill_between(x,[1]+[r['ci95'][0] for r in rs],[1]+[r['ci95'][1] for r in rs],alpha=.13,color=line.get_color())
    ax.axhline(1,color='gray',linewidth=.7);ax.set(xlabel='Injected mask count K',ylabel='Measured total-time ratio (baseline K=10)',xticks=[10,50,100,300])
    ax.grid(alpha=.2);ax.legend(fontsize=8,frameon=False)
    fig.savefig(OUT/'mask_dose_response.pdf');fig.savefig(OUT/'mask_dose_response.png',dpi=180);plt.close(fig)
    print('Generated extension from',len(sources),'locked source files')


if __name__=='__main__': main()
